import CoreGraphics

/// Muscle geometry for the body diagram, male and female, front and back.
///
/// Generated from `Laser_lace_260.svg` — the four figures were split into their
/// component subpaths, then every one was assigned to a muscle by hand. The
/// assignment is not derived from position heuristics: those were tried, got
/// roughly four fifths of it right, and the wrong fifth is invisible until
/// someone notices the diagram claims they trained their rear delts when they
/// trained their triceps.
///
/// Coordinates are normalised per figure into a unit square, x left-to-right and
/// y crown-to-feet, so the renderer scales each axis by the view's own size.
///
/// **A region can name more than one muscle.** Where the artwork draws two
/// muscles as a single shape — the middle and lower trapezius are one band here
/// — the region carries both, and the renderer colours it by whichever has seen
/// the most work. Tracking stays separate even though the drawing cannot.
///
/// **Upper and lower chest share one path.** The source has a single pectoral
/// shape per side, so the two are drawn by clipping it into an upper and a lower
/// window with a hairline gap between them. That gap is the dividing line; there
/// is no separate stroke.
enum BodyArt {

    struct Region {
        let groups: [MuscleGroup]
        let clip: CGRect?
        let d: String

        init(_ groups: [MuscleGroup], clip: CGRect?, d: String) {
            self.groups = groups
            self.clip = clip
            self.d = d
        }
    }

    /// Which figure to draw. `.other` takes the male figure — a body map has to
    /// draw something, and picking one is less bad than drawing nothing.
    static func figure(for sex: BiologicalSex) -> Figure {
        sex == .female ? .female : .male
    }

    enum Figure { case male, female }

    static func front(_ figure: Figure) -> [Region] {
        figure == .male ? maleFront : femaleFront
    }

    static func back(_ figure: Figure) -> [Region] {
        figure == .male ? maleBack : femaleBack
    }

    static func frontSilhouette(_ figure: Figure) -> [String] {
        figure == .male ? maleFrontSilhouette : femaleFrontSilhouette
    }

    static func backSilhouette(_ figure: Figure) -> [String] {
        figure == .male ? maleBackSilhouette : femaleBackSilhouette
    }

    /// Male and female differ here — 1.87 against 2.15 — so a single constant
    /// would letterbox one of them.
    static func aspect(_ figure: Figure) -> CGFloat {
        figure == .male ? maleFrontAspect : femaleFrontAspect
    }

